"""Exercise the supported invoice fixture and golden regeneration commands."""

import pytest

from billing import invoice


def test_regenerate_golden_files_in_new_directory(tmp_path):
    directory = tmp_path / "golden"
    paths = invoice.regen_golden(directory)
    assert paths == [directory / f"{number}.txt" for number in sorted(invoice.FIXTURES)]
    for path in paths:
        assert path.read_text() == invoice.render(invoice.FIXTURES[path.stem]())


def test_cli_regenerate(monkeypatch, tmp_path, capsys):
    monkeypatch.setattr(invoice, "GOLDEN_DIR", tmp_path)
    regenerate = invoice.regen_golden
    monkeypatch.setattr(invoice, "regen_golden", lambda: regenerate(tmp_path))
    assert invoice.main(["--regen-golden"]) == 0
    assert capsys.readouterr().out == "wrote 2 golden files\n"
    assert len(list(tmp_path.glob("*.txt"))) == 2


def test_cli_prints_fixture(capsys):
    assert invoice.main(["INV-2024-0107"]) == 0
    assert capsys.readouterr().out == invoice.render(invoice.FIXTURES["INV-2024-0107"]())


@pytest.mark.parametrize("args", [[], ["unknown"]])
def test_cli_rejects_missing_or_unknown_fixture(args, capsys):
