"""Accounting export validation and offline ERP delivery tests."""

import io
import json
from dataclasses import replace
from urllib.error import HTTPError, URLError
from unittest.mock import MagicMock, Mock

import pytest

from billing import export, invoice


@pytest.fixture
def upgrade():
    return invoice.FIXTURES["INV-2024-0107"]()


@pytest.mark.parametrize("customer,message", [
    ("No GSTIN", "no GSTIN"),
    ("Buyer (GSTIN 00ABCDE1234F1Z5)", "invalid state code"),
    ("Buyer (GSTIN 39ABCDE1234F1Z5)", "invalid state code"),
    ("Buyer (GSTIN AAABCDE1234F1Z5)", "invalid state code"),
])
def test_gstin_validation(upgrade, customer, message):
    with pytest.raises(export.ExportError, match=message):
        export.ledger_csv([replace(upgrade, customer=customer)])


def test_export_rejects_empty_invoice(upgrade):
    with pytest.raises(export.ExportError, match="no lines"):
        export.totals(replace(upgrade, lines=[], proration=None))


def test_ledger_rejects_unsupported_currency(upgrade):
    with pytest.raises(export.ExportError, match="supports"):
        export.ledger_csv([upgrade], currency="USD")


def test_ledger_rejects_net_credit_notes(upgrade):
    credit_note = replace(upgrade, lines=[("Refund", -100)], proration=None)
    with pytest.raises(export.ExportError, match="credit note"):
        export.ledger_csv([credit_note])


def test_ledger_rejects_duplicate_numbers(upgrade):
    with pytest.raises(export.ExportError, match="duplicate invoice numbers"):
        export.ledger_csv([upgrade, upgrade])


def test_erp_line_limit_includes_proration_credit(upgrade):
    inv = replace(upgrade, lines=[("Charge", 100)] * export.ERP_MAX_LINES)
    with pytest.raises(export.ExportError, match="100 lines exceeds"):
        export.erp_payload(inv)
    assert len(json.loads(export.erp_payload(replace(inv, proration=None)))["lines"]) == 99


def response(doc):
    result = MagicMock()
    result.__enter__.return_value.read.return_value = json.dumps(doc).encode()
    return result


def http_error(code, doc=None):
    return HTTPError("https://erp.test", code, "error", {},
                     io.BytesIO(json.dumps(doc or {}).encode()))


@pytest.fixture
def gateway(monkeypatch):
    urlopen = Mock()
    sleep = Mock()
    monkeypatch.setattr(export.urllib.request, "urlopen", urlopen)
    monkeypatch.setattr(export.time, "sleep", sleep)
    return urlopen, sleep


def test_send_upgrade_payload_and_headers(upgrade, gateway):
    urlopen, sleep = gateway
    urlopen.return_value = response({"document_id": "erp-107"})
    assert export.send_to_erp(upgrade, url="https://erp.test", token="secret") == "erp-107"
    request = urlopen.call_args.args[0]
    assert request.full_url == "https://erp.test"
    assert request.method == "POST"
    assert request.get_header("Authorization") == "Bearer secret"
    assert request.get_header("Idempotency-key") == "inv-INV-2024-0107"
    assert request.get_header("Content-type") == "application/json"
    assert json.loads(request.data) == json.loads(export.erp_payload(upgrade))
    assert urlopen.call_args.kwargs == {"timeout": 20}
    sleep.assert_not_called()


def test_send_retries_transient_failures_with_backoff(upgrade, gateway):
    urlopen, sleep = gateway
    urlopen.side_effect = [http_error(429), http_error(503), URLError("offline"),
                           response({"document_id": "erp-107"})]
    assert export.send_to_erp(upgrade) == "erp-107"
    assert urlopen.call_count == 4
    assert [call.args[0] for call in sleep.call_args_list] == [1, 4, 15]


@pytest.mark.parametrize("failure,message", [
    (http_error(400), "rejected the invoice"),
    (http_error(409), "duplicate delivery without a document id"),
    (response({}), "returned no document_id"),
])
def test_send_permanent_failure_is_not_retried(upgrade, gateway, failure, message):
    urlopen, sleep = gateway
    if isinstance(failure, Exception):
        urlopen.side_effect = failure
    else:
        urlopen.return_value = failure
    with pytest.raises(export.DeliveryError, match=message):
        export.send_to_erp(upgrade)
    assert urlopen.call_count == 1
    sleep.assert_not_called()


def test_send_duplicate_returns_existing_document(upgrade, gateway):
    urlopen, sleep = gateway
    urlopen.side_effect = http_error(409, {"document_id": "existing-107"})
    assert export.send_to_erp(upgrade) == "existing-107"
    sleep.assert_not_called()


def test_send_stops_after_retry_budget(upgrade, gateway):
    urlopen, sleep = gateway
    urlopen.side_effect = URLError("offline")
    with pytest.raises(export.DeliveryError, match="failed after 4 attempts.*offline"):
        export.send_to_erp(upgrade)
    assert urlopen.call_count == 4
    assert sleep.call_count == 3
